                        Context.NINJA_PROPERTIES_X_FORWARDED_FOR, false);

        String remoteAddr;

        if (!isUsageOfXForwardedHeaderEnabled) {
            remoteAddr = httpServletRequest.getRemoteAddr();
        } else {
            remoteAddr = calculateRemoteAddrAndTakeIntoAccountXForwardHeader();
        }

        return remoteAddr;
