    /**
     * EntityExplodeEvent.
     * @param event EntityExplodeEvent
     */
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onEntityExplodeChangeBlock(final EntityExplodeEvent event) {

        if (event.blockList().isEmpty()) {
            return;
        }
        String name;
        String action = "entity-explode";
        if (event.getEntity() != null) {
            if (event.getEntity() instanceof Creeper) {
                if (!Prism.getIgnore().event("creeper-explode", event.getEntity().getWorld())) {
                    return;
                }
                action = "creeper-explode";
                name = "creeper";
            } else if (event.getEntity() instanceof TNTPrimed) {
                if (!Prism.getIgnore().event("tnt-explode", event.getEntity().getWorld())) {
                    return;
                }
                action = "tnt-explode";
                Entity source = ((TNTPrimed) event.getEntity()).getSource();
                name = followTntTrail(source);
            } else if (event.getEntity() instanceof EnderDragon) {
                if (!Prism.getIgnore().event("dragon-eat", event.getEntity().getWorld())) {
                    return;
                }
                action = "dragon-eat";
                name = "enderdragon";
            } else {
                if (!Prism.getIgnore().event("entity-explode", event.getLocation().getWorld())) {
                    return;
                }
                try {
                    name = event.getEntity().getType().name().toLowerCase().replace("_", " ");
                    name = name.length() > 15 ? name.substring(0, 15) : name; // I
                } catch (final NullPointerException e) {
                    name = "unknown";
                }
            }
        } else {
            if (!Prism.getIgnore().event("entity-explode", event.getLocation().getWorld())) {
                return;
            }
            name = "magic";
        }
        contructBlockEvent(action,name,event.blockList());
    }

    private String followTntTrail(Entity initial) {
        int counter = 10000000;

        while (initial != null) {
            if (initial instanceof Player) {
                return initial.getName();
            } else if (initial instanceof TNTPrimed) {
                initial = (((TNTPrimed) initial).getSource());
                if (counter < 0 && initial != null) {
                    Location last = initial.getLocation();
                    plugin.getLogger().warning("TnT chain has exceeded one million, will not continue!");
                    plugin.getLogger().warning("Last Tnt was at " + last.getX() + ", " + last.getY() + ". "
                            + last.getZ() + " in world " + last.getWorld());
                    return "tnt";
                }
                counter--;
            } else {
                return initial.getType().name();
            }
        }

        return "tnt";
    }
}

package me.botsko.prism.utils;

import org.bukkit.Chunk;
import org.bukkit.Material;
import org.bukkit.block.Block;
import org.bukkit.block.data.BlockData;
import org.bukkit.entity.Player;
import org.bukkit.util.Vector;

import java.util.ArrayList;

public class ChunkUtils {

    /**
     * Resets the preview border blocks.
     *
     * @param player Player
     * @param blocks Iterable Block list,
     */
    public static void resetPreviewBoundaryBlocks(Player player, Iterable<Block> blocks) {
        for (Block block : blocks) {
            EntityUtils.sendBlockChange(player, block.getLocation(), block.getBlockData());
        }
    }

    /**
     * Sets a block in preview mode around the border of a chunk.
     *
     * @param player Player
     * @param blocks Iterable Block list,
     */
    public static void setPreviewBoundaryBlocks(Player player, Iterable<Block> blocks, Material m) {
        BlockData blockData = m.createBlockData();
        for (Block block : blocks) {
            EntityUtils.sendBlockChange(player, block.getLocation(), blockData);
        }
    }

    /**
     * Returns the minimum vector for the chunk.
     *
     * @param chunk Chunk
     * @return Vector
     */
    public static Vector getChunkMinVector(Chunk chunk) {
        int blockMinX = chunk.getX() * 16;
        int blockMinZ = chunk.getZ() * 16;
        return new Vector(blockMinX, 0, blockMinZ);
    }

    /**
     * Returns the maximum vector for the chunk.
     *
     * @param chunk Chunk
     * @return Vector
     */
    public static Vector getChunkMaxVector(Chunk chunk) {
        int blockMinX = chunk.getX() * 16;
        int blockMinZ = chunk.getZ() * 16;
        int blockMaxX = blockMinX + 15;
        int blockMaxZ = blockMinZ + 15;
        return new Vector(blockMaxX, chunk.getWorld().getMaxHeight(), blockMaxZ);
    }

    /**
     * Returns an array of boundary blocks at a single Y for the current chunk.
     *
     * @param chunk chunk
     * @param y height
     * @return List of Blocks
     */
    public static ArrayList<Block> getBoundingBlocksAtY(Chunk chunk, int y) {

        int blockMinX = chunk.getX() * 16;
        int blockMinZ = chunk.getZ() * 16;
        int blockMaxX = blockMinX + 15;
        int blockMaxZ = blockMinZ + 15;

        ArrayList<Block> blocks = new ArrayList<>();

        // MinX -> MinZ
        for (int x = blockMinX; x < blockMaxX; x++) {
            blocks.add(chunk.getWorld().getBlockAt(x, y, blockMinZ));
        }
        // MinX -> MaxZ
        for (int x = blockMinX; x < blockMaxX; x++) {
            blocks.add(chunk.getWorld().getBlockAt(x, y, blockMaxZ));
        }
        // MinZ -> MinX
        for (int z = blockMinZ; z < blockMaxZ; z++) {
            blocks.add(chunk.getWorld().getBlockAt(blockMinX, y, z));
        }
        // MinZ -> MaxX
        for (int z = blockMinZ; z < blockMaxZ; z++) {
            blocks.add(chunk.getWorld().getBlockAt(blockMaxX, y, z));
        }

        return blocks;

    }
}

package me.botsko.prism.utils;

import org.bukkit.NamespacedKey;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.inventory.ItemStack;

import java.util.Map;

public class EnchantmentUtils {

    /**
     * Given an enchantment, does the current item have any that conflict.
     *
     * @return bool
     */
    @SuppressWarnings("unused")
    public static boolean hasConflictingEnchanment(ItemStack item, Enchantment ench) {
        Map<Enchantment, Integer> enchantments = item.getEnchantments();
        boolean conflict = false;
        for (Enchantment e : enchantments.keySet()) {
            if (ench.conflictsWith(e)) {
                conflict = true;
            }
        }
        return (enchantments.containsKey(ench) || conflict);
    }

    /**
     * Return the enchantment based on a common name.
     *
     * @param name String
     * @return Enchantment
     */
    @SuppressWarnings("unused")
    public static Enchantment getEnchantmentFromCommonName(String name) {
        switch (name.toLowerCase()) {
            case "aquaaffinity":
                return Enchantment.WATER_WORKER;
            case "bane":
                return Enchantment.DAMAGE_ARTHROPODS;
            case "efficiency":
                return Enchantment.DIG_SPEED;
            case "explosion":
                return Enchantment.PROTECTION_EXPLOSIONS;
            case "fall":
                return Enchantment.PROTECTION_FALL;
            case "fire":
                return Enchantment.PROTECTION_FIRE;
            case "fireaspect":
                return Enchantment.FIRE_ASPECT;
            case "flame":
                return Enchantment.ARROW_FIRE;
            case "fortune":
                return Enchantment.LOOT_BONUS_BLOCKS;
            case "infinity":
                return Enchantment.ARROW_INFINITE;
            case "knockback":
                return Enchantment.KNOCKBACK;
            case "power":
                return Enchantment.ARROW_DAMAGE;
            case "looting":
                return Enchantment.LOOT_BONUS_MOBS;
            case "projectile":
                return Enchantment.PROTECTION_PROJECTILE;
            case "protection":
                return Enchantment.PROTECTION_ENVIRONMENTAL;
            case "punch":
                return Enchantment.ARROW_KNOCKBACK;
            case "respiration":
                return Enchantment.OXYGEN;
            case "sharpness":
                return Enchantment.DAMAGE_ALL;
            case "silktouch":
                return Enchantment.SILK_TOUCH;
            case "smite":
                return Enchantment.DAMAGE_UNDEAD;
            case "unbreaking":
                return Enchantment.DURABILITY;
            default:
                String formattedName = name.replace(' ','_');
                NamespacedKey key = NamespacedKey.minecraft(formattedName);
                return Enchantment.getByKey(key);
        }
    }

    /**
     * Return the common name for an enchantment.
     *
     * @param enchantment Keyed
     * @param level int
     * @return String
     */
    public static String getClientSideEnchantmentName(Enchantment enchantment, int level) {

        String enchantName;

        if (enchantment.equals(Enchantment.ARROW_DAMAGE)) {
            enchantName = "power";
        } else if (enchantment.equals(Enchantment.ARROW_FIRE)) {
            enchantName = "flame";
        } else if (enchantment.equals(Enchantment.ARROW_INFINITE)) {
            enchantName = "infinity";
        } else if (enchantment.equals(Enchantment.ARROW_KNOCKBACK)) {
            enchantName = "punch";
        } else if (enchantment.equals(Enchantment.DAMAGE_ALL)) {
            enchantName = "sharpness";
        } else if (enchantment.equals(Enchantment.DAMAGE_ARTHROPODS)) {
            enchantName = "bane of anthropods";
        } else if (enchantment.equals(Enchantment.DAMAGE_UNDEAD)) {
            enchantName = "damage undead";
        } else if (enchantment.equals(Enchantment.DIG_SPEED)) {
            enchantName = "efficiency";
        } else if (enchantment.equals(Enchantment.DURABILITY)) {
            enchantName = "unbreaking";
        } else if (enchantment.equals(Enchantment.LOOT_BONUS_BLOCKS)) {
            enchantName = "fortune";
        } else if (enchantment.equals(Enchantment.LOOT_BONUS_MOBS)) {
            enchantName = "looting";
        } else if (enchantment.equals(Enchantment.OXYGEN)) {
            enchantName = "respiration";
        } else if (enchantment.equals(Enchantment.PROTECTION_ENVIRONMENTAL)) {
            enchantName = "protection";
        } else if (enchantment.equals(Enchantment.PROTECTION_EXPLOSIONS)) {
            enchantName = "blast protection";
        } else if (enchantment.equals(Enchantment.PROTECTION_FALL)) {
            enchantName = "feather falling";
        } else if (enchantment.equals(Enchantment.PROTECTION_FIRE)) {
            enchantName = "fire protection";
        } else if (enchantment.equals(Enchantment.PROTECTION_PROJECTILE)) {
            enchantName = "projectile protection";
        } else if (enchantment.equals(Enchantment.WATER_WORKER)) {
            enchantName = "aqua affinity";
        } else if (enchantment.equals(Enchantment.VANISHING_CURSE)) {
            enchantName = "vanishing curse";
        } else {
            // can leave as-is: SILK_TOUCH, FIRE_ASPECT, KNOCKBACK, THORNS, LUCK, LURE
            enchantName = enchantment.getKey().getKey().toLowerCase().replace("_", " ");
        }
        switch (level) {
            case 1:
                enchantName += " I";
                break;
            case 2:
                enchantName += " II";
                break;
            case 3:
                enchantName += " III";
                break;
            case 4:
                enchantName += " IV";
                break;
            case 5:
                enchantName += " V";
                break;
            default:
                enchantName += " " + level;
        }
        return enchantName;

    }
}

